export const CASPIAN_FIRESTORE_RULES = "rules_version = '2';\nservice cloud.firestore {\n  match /databases/{database}/documents {\n\n    // Admin signal — claim-first, Firestore fallback. The Firebase Auth\n    // custom claim `role` is the primary admin signal as of v8.4.1; the\n    // Firestore read is a fallback for admins promoted before v8.4.1 (or\n    // before their token has rotated to pick up the new claim). Storage\n    // rules check the same predicate so consumer admin authorization\n    // works identically across services.\n    function isAdmin() {\n      return request.auth != null\n          && (request.auth.token.role == 'admin'\n              || (exists(/databases/$(database)/documents/users/$(request.auth.uid))\n                  && get(/databases/$(database)/documents/users/$(request.auth.uid)).data.role == 'admin'));\n    }\n\n    function isAuth() {\n      return request.auth != null;\n    }\n\n    // Staff signal (v10.0.0) — the POS cashier role. Same claim-first,\n    // Firestore-fallback shape as isAdmin(), and deliberately inclusive of\n    // 'admin': an owner working the counter must not need a second account.\n    // Staff reach the register at /pos and read the catalog; they are denied\n    // every admin surface (AdminGuard still requires 'admin') and every\n    // settings write. `syncUserRoleClaim` mirrors users/{uid}.role onto the\n    // Auth custom claim so the fast path needs no document read.\n    function isStaff() {\n      return request.auth != null\n          && (request.auth.token.role in ['staff', 'admin']\n              || (exists(/databases/$(database)/documents/users/$(request.auth.uid))\n                  && get(/databases/$(database)/documents/users/$(request.auth.uid)).data.role in ['staff', 'admin']));\n    }\n\n    match /products/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    match /productCategories/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    match /productBrands/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    // Generic product-taxonomy terms (materials, seasons, colors, …). Public\n    // read so the storefront can filter/display; admin-only write. Same posture\n    // as productCategories / productBrands.\n    match /taxonomyTerms/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    match /productCollections/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    match /orders/{id} {\n      allow read: if isAdmin() || (isAuth() && resource.data.userId == request.auth.uid);\n      allow create: if isAuth();\n      allow update: if isAdmin();\n    }\n\n    match /users/{uid} {\n      allow read: if isAuth() && request.auth.uid == uid;\n      // On create: a user can write their own profile; role must be absent\n      // or explicitly 'customer'. This is the only path — on first sign-in\n      // resource.data is null, so the update-rule's role-equality check\n      // (request.resource.data.role == resource.data.role) would fail\n      // against null and silently deny the write, leaving userProfile null\n      // in auth-context and every profile-dependent UI card blank.\n      allow create: if isAuth() && request.auth.uid == uid\n                    && (!('role' in request.resource.data) || request.resource.data.role == 'customer');\n      // On update: role must stay as it is on the existing doc — blocks\n      // self-promotion. Admin writes go through the isAdmin() branch below.\n      allow update: if isAuth() && request.auth.uid == uid\n                    && (!('role' in request.resource.data) || request.resource.data.role == resource.data.role);\n      allow read, write: if isAdmin();\n    }\n\n    match /carts/{uid} {\n      // Owner reads/writes their own cart. Admins may READ any cart so the\n      // admin user-detail view can show what a shopper currently has in their\n      // bag; admins never write someone else's cart.\n      allow read: if isAuth() && (request.auth.uid == uid || isAdmin());\n      allow write: if isAuth() && request.auth.uid == uid;\n    }\n\n    match /reviews/{id} {\n      allow read: if resource.data.status == 'approved' || isAdmin();\n      allow create: if isAuth()\n        && request.resource.data.userId == request.auth.uid\n        && request.resource.data.status == 'pending'\n        && request.resource.data.rating is number\n        && request.resource.data.rating >= 1\n        && request.resource.data.rating <= 5;\n      allow update, delete: if isAdmin();\n    }\n\n    match /questions/{id} {\n      allow read: if resource.data.status == 'approved' || isAdmin();\n      allow create: if isAuth()\n        && request.resource.data.userId == request.auth.uid\n        && request.resource.data.status == 'pending';\n      allow update, delete: if isAdmin();\n    }\n\n    match /promoCodes/{id} {\n      allow read: if isAuth();\n      allow write: if isAdmin();\n    }\n\n    // Shipping plugin installs — public read so the checkout calculator and\n    // the public /shipping page can enumerate offered methods. Admin-only\n    // write prevents shoppers from tampering with pricing.\n    match /shippingPluginInstalls/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    // Payment plugin installs — public read so `useCheckout` on the storefront\n    // can discover which provider to invoke. Only publishable (`pk_`-style)\n    // credentials live here; server-side secrets are Cloud Functions secrets.\n    // Admin-only write prevents shoppers from tampering with enabled providers.\n    match /paymentPluginInstalls/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    // Email plugin installs — admin-only read AND write. The plugin config\n    // stores the provider API key (SendGrid / Brevo). Cloud Functions read\n    // via the Admin SDK, which bypasses rules. Shoppers never need to see\n    // this collection, unlike shipping/payment installs. Added in v2.14.\n    match /emailPluginInstalls/{id} {\n      allow read: if isAdmin();\n      allow write: if isAdmin();\n    }\n\n    // Instagram channel connection — server-only. The single `instagram/connection`\n    // doc holds the IG Business account id and the access tokens (long-lived user\n    // token + Page token), written/read only by the functions-instagram Cloud\n    // Functions (Admin SDK, which bypasses rules). These are secrets, so deny ALL\n    // client access. Clients (the admin panel and the register) talk to the\n    // callables, which return connection status + feed + comments — never a token.\n    match /instagram/{id} {\n      allow read, write: if false;\n    }\n\n    match /faqs/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    match /journal/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    match /pageContents/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    // Page builder (v9.26.0). PUBLISHED layouts are public-read (the storefront\n    // renders from them), admin-write; their `revisions` subcollection is\n    // admin-only history. WORKING DRAFTS and publish SCHEDULES are admin-only\n    // read AND write, so unpublished content never leaks. `builderPages` is the\n    // public-read custom-page registry (drafts hidden in app code, not rules).\n    match /pageLayouts/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n      match /revisions/{version} {\n        allow read, write: if isAdmin();\n      }\n    }\n    match /pageLayoutDrafts/{id} {\n      allow read, write: if isAdmin();\n    }\n    match /pageLayoutSchedules/{id} {\n      allow read, write: if isAdmin();\n    }\n    match /builderPages/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    match /languages/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    match /subscribers/{id} {\n      allow create: if true;\n      allow read, delete: if isAdmin();\n    }\n\n    // Contact-form submissions (v2.13). Public create so unauthenticated\n    // visitors can send a message; shape + length clamps blunt spam/abuse.\n    // Admin-only read/update/delete — submissions are never shown publicly.\n    // `status` is pinned to 'new' on create so the bell badge counts\n    // everything that comes in; admins flip to 'read'/'archived'.\n    match /contacts/{id} {\n      allow create: if request.resource.data.status == 'new'\n                    && request.resource.data.name is string\n                    && request.resource.data.name.size() > 0\n                    && request.resource.data.name.size() <= 120\n                    && request.resource.data.email is string\n                    && request.resource.data.email.size() > 0\n                    && request.resource.data.email.size() <= 200\n                    && request.resource.data.message is string\n                    && request.resource.data.message.size() > 0\n                    && request.resource.data.message.size() <= 5000\n                    && (!('subject' in request.resource.data)\n                        || (request.resource.data.subject is string\n                            && request.resource.data.subject.size() <= 200));\n      allow read, update, delete: if isAdmin();\n    }\n\n    // Search-term analytics — storefront visitors upsert a doc per\n    // normalized query (count + timestamps). Admin-only read/delete.\n    // Shape is validated but writes are public: the data is analytics,\n    // not security-sensitive, and forcing auth would drop anonymous\n    // shoppers out of the funnel.\n    match /searchTerms/{id} {\n      allow read, delete: if isAdmin();\n      allow create: if request.resource.data.term is string\n                    && request.resource.data.term.size() > 0\n                    && request.resource.data.term.size() <= 200\n                    && request.resource.data.count == 1;\n      allow update: if request.resource.data.term == resource.data.term\n                    && request.resource.data.count is number\n                    && request.resource.data.count > resource.data.count;\n    }\n\n    match /settings/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    match /scriptSettings/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    // Admin todo list — admins only for both read and write. Contains\n    // internal setup/operational tasks, not shopper-facing content.\n    match /adminTodos/{id} {\n      allow read: if isAdmin();\n      allow write: if isAdmin();\n    }\n\n    // Setup-wizard email allowlist for the very first admin (v8.7.0).\n    // Doc id is the lowercase, trimmed email. The wizard's \"Designate by\n    // email\" path writes here BEFORE any admin exists; once the named\n    // user signs up, `onUserCreate` promotes them and deletes the doc.\n    //\n    // - Public read so the wizard can confirm a designation already exists.\n    // - Public create — but a doc can only be written ONCE per email\n    //   (`!exists`), shape is validated, and the email must equal the\n    //   doc id. The bigger safety invariant (\"no admin exists yet\") is\n    //   enforced server-side in `onUserCreate`: if an admin already\n    //   exists, the trigger ignores all pending entries, so a stale\n    //   write here can't escalate privilege.\n    // - Update forbidden — re-designate by delete + recreate.\n    // - Delete restricted to admins (so post-install revocation goes\n    //   through the admin panel; pre-install installers who fat-finger\n    //   the email can fix it by signing up under the typo'd address\n    //   to consume the entry, or by simply typing it correctly the\n    //   second time — distinct emails create distinct docs).\n    match /pendingSuperAdmin/{email} {\n      allow read: if true;\n      allow create: if !exists(/databases/$(database)/documents/pendingSuperAdmin/$(email))\n                    && request.resource.data.keys().hasOnly(['email', 'designatedAt'])\n                    && request.resource.data.email is string\n                    && request.resource.data.email.size() > 0\n                    && request.resource.data.email.size() <= 320\n                    && request.resource.data.email == email;\n      allow delete: if isAdmin();\n    }\n\n    // Transactional email config (v2.11). Admin-only on both read and write —\n    // contains sender addresses, admin recipient lists, and unfiltered\n    // template bodies that shouldn't leak to shoppers. Cloud Functions\n    // bypass rules via the Admin SDK.\n    match /emailSettings/{id} {\n      allow read: if isAdmin();\n      allow write: if isAdmin();\n    }\n    match /emailTemplates/{id} {\n      allow read: if isAdmin();\n      allow write: if isAdmin();\n    }\n\n    // Error logs (mod1182). Writes are public because crashes happen in\n    // unauthenticated shopper sessions too — gate abuse with a strict shape\n    // check (required scalar fields, capped string lengths, fixed source\n    // enum, forbidden admin fields). Reads, updates, and deletes are\n    // admin-only: the panel at /admin/about lists them, the admin dismisses\n    // them, and the scheduled retention sweep trims them. Cloud Functions\n    // write via the Admin SDK which bypasses rules entirely.\n    match /errorLogs/{id} {\n      allow create: if request.resource.data.source in ['client', 'service', 'cloud-function']\n                    && request.resource.data.origin is string\n                    && request.resource.data.origin.size() > 0\n                    && request.resource.data.origin.size() <= 200\n                    && request.resource.data.message is string\n                    && request.resource.data.message.size() > 0\n                    && request.resource.data.message.size() <= 2000\n                    && (!('stack' in request.resource.data)\n                        || (request.resource.data.stack is string\n                            && request.resource.data.stack.size() <= 4000))\n                    && request.resource.data.libraryVersion is string\n                    && request.resource.data.libraryVersion.size() <= 40\n                    && request.resource.data.seenCount == 1;\n      allow read, update, delete: if isAdmin();\n    }\n\n    // --- Point of sale (v10.0.0) ---\n\n    // Till sessions. Written ONLY by the caspian-pos Cloud Functions via the\n    // Admin SDK (which bypasses rules), never from the register — otherwise a\n    // cashier could edit `expectedCash` to paper over a drawer variance.\n    // Staff read so the register can show its own open shift and the X-report.\n    match /posSessions/{id} {\n      allow read: if isStaff();\n      allow write: if false;\n    }\n\n    // Register registry: one document per physical till / browser profile.\n    // Staff read (the register resolves its own label + saved locale on boot);\n    // admins name and retire registers from the admin panel.\n    match /posDevices/{id} {\n      allow read: if isStaff();\n      allow write: if isAdmin();\n    }\n\n    // Monotonic receipt-number counter (`posCounters/receipt`). Server-only on\n    // both sides: allocation happens inside the commitPosSale transaction, and\n    // a client that could read it would learn the store's total sale count.\n    match /posCounters/{id} {\n      allow read, write: if false;\n    }\n\n    // Sold per-computer POS licenses. Server-only: `activatePosLicense` binds a\n    // key to the first deviceId that presents it, and the documents carry\n    // customer contact details. A register learns its own status from the\n    // callable's response, never by reading the collection.\n    match /posLicenses/{id} {\n      allow read, write: if false;\n    }\n  }\n}\n";

export const CASPIAN_STORAGE_RULES = "rules_version = '2';\r\n\r\n// Recommended Storage rules for a Caspian Store installation. Deploy with\r\n//   firebase deploy --only storage\r\nservice firebase.storage {\r\n  match /b/{bucket}/o {\r\n\r\n    // Admin signal — claim-first, Firestore fallback. v8.4.1 introduced an\r\n    // Auth custom claim `role` so this rule can authorize without a\r\n    // cross-service Firestore read; the read is kept as a fallback so\r\n    // admins promoted before v8.4.1 (or via the legacy grant-admin script\r\n    // before it was updated) are still recognized while their token rotates.\r\n    // The custom claim is set by the `claimAdmin` callable, the\r\n    // `onUserCreate` trigger, and the `syncAdminClaim` Firestore trigger\r\n    // that reconciles the claim with `users/{uid}.role` on every write.\r\n    function isAdmin() {\r\n      return request.auth != null\r\n          && (request.auth.token.role == 'admin'\r\n              || firestore.get(\r\n                   /databases/(default)/documents/users/$(request.auth.uid)\r\n                 ).data.role == 'admin');\r\n    }\r\n\r\n    // Profile avatars live under users/{uid}/<filename>. Storage rules grammar\r\n    // doesn't allow wildcards inside a segment, so we match any single-segment\r\n    // filename; the content-type + size guards below do the real validation.\r\n    // Anyone can read (product pages show avatars in review cards).\r\n    match /users/{uid}/{filename} {\r\n      allow read: if true;\r\n      allow write: if request.auth != null\r\n                   && request.auth.uid == uid\r\n                   && request.resource.size < 5 * 1024 * 1024\r\n                   && request.resource.contentType.matches('image/(jpeg|png|webp)');\r\n      allow delete: if request.auth != null && request.auth.uid == uid;\r\n    }\r\n\r\n    // Journal cover images — public read, admin write up to 10 MB.\r\n    match /journal/{path=**} {\r\n      allow read: if true;\r\n      allow write: if isAdmin()\r\n                   && request.resource.size < 10 * 1024 * 1024\r\n                   && request.resource.contentType.matches('image/(jpeg|png|webp|gif)');\r\n      allow delete: if isAdmin();\r\n    }\r\n\r\n    // Page content assets (optional image uploads from <AdminPagesPage>).\r\n    match /pageContents/{path=**} {\r\n      allow read: if true;\r\n      allow write: if isAdmin()\r\n                   && request.resource.size < 10 * 1024 * 1024\r\n                   && request.resource.contentType.matches('image/(jpeg|png|webp|gif)');\r\n      allow delete: if isAdmin();\r\n    }\r\n\r\n    // Site-settings branding assets — logo and favicon uploaded from\r\n    // <AdminSiteSettingsPage>. Public read (the storefront renders the logo\r\n    // on every page), admin write up to 10 MB. SVG is allowed here because\r\n    // logos/favicons are commonly vector.\r\n    match /siteSettings/{path=**} {\r\n      allow read: if true;\r\n      allow write: if isAdmin()\r\n                   && request.resource.size < 10 * 1024 * 1024\r\n                   && request.resource.contentType.matches('image/(jpeg|png|webp|gif|svg\\\\+xml)');\r\n      allow delete: if isAdmin();\r\n    }\r\n\r\n    // Product catalog images uploaded from <AdminProductEditor>. Public read\r\n    // (every PLP/PDP card shows these), admin write up to 10 MB. No SVG here\r\n    // — product photos should be raster, and blocking SVG avoids embedded-\r\n    // script exploits from less-trusted sources.\r\n    match /products/{path=**} {\r\n      allow read: if true;\r\n      allow write: if isAdmin()\r\n                   && request.resource.size < 10 * 1024 * 1024\r\n                   && request.resource.contentType.matches('image/(jpeg|png|webp|gif)');\r\n      allow delete: if isAdmin();\r\n    }\r\n\r\n    // Category featured images uploaded from <AdminCategoryEditor>. Public read\r\n    // (the homepage featured-categories section + header mega-menu render them),\r\n    // admin write up to 10 MB. No SVG — these are photos.\r\n    match /categories/{path=**} {\r\n      allow read: if true;\r\n      allow write: if isAdmin()\r\n                   && request.resource.size < 10 * 1024 * 1024\r\n                   && request.resource.contentType.matches('image/(jpeg|png|webp|gif)');\r\n      allow delete: if isAdmin();\r\n    }\r\n  }\r\n}\r\n";
